/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

/** An element's box for one gesture, from `measuredBox`. */
export interface MeasuredBox {
  /** The box: measured the first time, and again only after the page scrolled or resized. */
  get: () => DOMRect;
  /** Stops watching the page. Call it when the gesture ends. */
  stop: () => void;
}

/**
 * An element's box, measured once for a gesture rather than on each of its
 * moves. Read after a move wrote to the page, `getBoundingClientRect` makes
 * the browser lay the page out on the spot, every frame. A scroll or a resize
 * during the gesture moves the element, so either one measures it again.
 */
export function measuredBox(element: Element): MeasuredBox {
  let box: DOMRect | null = null;
  const view = element.ownerDocument?.defaultView;
  const stale = () => {
    box = null;
  };
  view?.addEventListener("scroll", stale, { capture: true, passive: true });
  view?.addEventListener("resize", stale, { passive: true });
  return {
    get: () => {
      box ??= element.getBoundingClientRect();
      return box;
    },
    stop: () => {
      view?.removeEventListener("scroll", stale, { capture: true });
      view?.removeEventListener("resize", stale);
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

import {
  css,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import {
  clamp,
  fractionOf,
  type NumberScale,
  numberFormatter,
  scrubTo,
  stepBy,
  stepFromKey,
  valueAt,
} from "@ui-sdk/core/number";
import {
  type ChangeDetails,
  type CommitDetails,
  createGestures,
  createReporter,
  definePrimitive,
  flag,
  VISUALLY_HIDDEN,
} from "../primitive";

/** How a drag turns a knob: up and down, around its centre, or by the turns of the pointer. */
export type KnobDragMode = "circular" | "revolution" | "vertical";

/** Center of the 48 by 48 viewBox the arcs are drawn in. */
const VIEWBOX_CENTER = 24;
/** Gap at the bottom of the dial: the sweep runs clockwise from bottom-left to bottom-right. */
const ANGLE_GAP_RAD = Math.PI / 5;
const TAU = Math.PI * 2;
const toDegrees = (radians: number) => (radians * 180) / Math.PI;
/** Rotation at `min`, in degrees clockwise from 12 o'clock. */
export const START_ANGLE = 90 + toDegrees(Math.PI / 2 + ANGLE_GAP_RAD);
/** Rotation travelled from `min` to `max`, in degrees. */
export const SWEEP_ANGLE = toDegrees(TAU - 2 * ANGLE_GAP_RAD);
/** Outer edge of the arcs in the viewBox; each stroke is centered inside it. */
const ARC_OUTER_RADIUS = 23;
/** The width of the track and indicator arcs in the 48 by 48 view box, unless given. */
export const DEFAULT_ARC_STROKE_WIDTH = 3;
/** Vertical drag: pointer travel, in px, for the whole `min` to `max` range. */
const VERTICAL_DRAG_RANGE_PX = 150;
/** Circular drag: inside this fraction of the diameter the angle is synced but not accumulated, so crossing the hub does not jump. */
const CENTER_DEAD_ZONE_REL = 0.08;
/** The smallest the hub's dead zone may be, in px, however small the knob. */
const CENTER_DEAD_ZONE_MIN_PX = 2;
/** A press that moves less than this is a tap; two quick taps reset the value. */
const TAP_MAX_MOVE_PX = 12;
/** The longest two taps may be apart, in ms, to count as a double tap. */
const DOUBLE_TAP_MAX_MS = 320;
/** A wheel movement smaller than this is ignored. */
const WHEEL_DELTA_EPSILON = 0.1;
/** Holding Shift turns the knob this much slower than the pointer moves. */
const FINE_DRAG = 0.25;
/** On a scale that is not linear, a key or wheel notch moves this share of the travel. */
const POSITION_STEP = 0.01;
/** On a scale that is not linear, a large step moves this share of the travel. */
const LARGE_POSITION_STEP = 0.1;

export interface KnobPrimitiveOptions {
  /** Value the indicator arc grows from, such as `0` on a -1 to 1 pan. Defaults to `min`. */
  anchor?: number;
  /** Uncontrolled starting value, and what a reset returns to; defaults to the middle of the travel. */
  defaultValue?: number;
  disabled?: boolean;
  /** @default "circular" */
  dragMode?: KnobDragMode;
  /** How the value is written, e.g. `{ maximumFractionDigits: 1 }`. */
  format?: Intl.NumberFormatOptions;
  /** Step for Page Up, Page Down and Shift with the arrow keys. @default 10 */
  largeStep?: number;
  locale?: Intl.LocalesArgument;
  /** @default 100 */
  max?: number;
  /** @default 0 */
  min?: number;
  /** The form field's name, which the native input carries. */
  name?: string;
  onValueChange?: (value: number, details: ChangeDetails) => void;
  onValueCommitted?: (value: number, details: CommitDetails) => void;
  /** `"linear"`, `"log"`, or a `{ to, from }` pair that maps values into an even space and back. @default "linear" */
  scale?: NumberScale;
  /** @default 1 */
  step?: number;
  /** The controlled value; leave it out for the knob to hold its own. */
  value?: number;
}

export interface KnobState {
  anchor: number | undefined;
  defaultValue: number | undefined;
  disabled: boolean;
  /** Where a drag has taken the value, held until release so a controlled value that lags cannot pull the knob back. */
  draft: number | null;
  dragging: boolean;
  dragMode: KnobDragMode;
  format: Intl.NumberFormatOptions | undefined;
  /** Whether a label part names the knob. */
  labelled: boolean;
  largeStep: number;
  locale: Intl.LocalesArgument | undefined;
  max: number;
  min: number;
  name: string | undefined;
  scale: NumberScale;
  step: number;
  /** The value the app holds, or the knob's own. */
  value: number;
}

/** What a view draws a knob from. */
export interface KnobSnapshot {
  anchor: number | undefined;
  /** Indicator arc origin, 0 to 1 along the sweep. */
  anchorPercent: number;
  /** Rotation in degrees, clockwise from 12 o'clock. */
  angle: number;
  disabled: boolean;
  dragging: boolean;
  dragMode: KnobDragMode;
  /** The value as text, with `format` and `locale`. */
  formatted: string;
  largeStep: number;
  max: number;
  min: number;
  /** Value position, 0 to 1 along the sweep. */
  percent: number;
  scale: NumberScale;
  step: number;
  /** The value as displayed: the dragged one while a pointer turns the knob. */
  value: number;
}

const range = (state: {
  largeStep?: number;
  max: number;
  min: number;
  step: number;
}) => ({
  largeStep: state.largeStep,
  max: state.max,
  min: state.min,
  step: state.step,
});

/** The value a fresh knob holds: the middle of its travel, on its scale and its grid. */
function middleOf(state: KnobState) {
  return scrubTo(valueAt(0.5, state, state.scale), range(state)).value;
}

/** What a reset returns to. */
const resetValue = (state: KnobState) => state.defaultValue ?? middleOf(state);

const onGrid = (state: KnobState, raw: number) =>
  scrubTo(raw, range(state)).value;

const displayed = (state: KnobState) =>
  state.draft ?? clamp(state.value, state.min, state.max);

export type { ChangeDetails, CommitDetails } from "../primitive";

const views = new WeakMap<KnobState, KnobSnapshot>();

/** What the parts draw from `state`, worked out once per state. */
export function viewOf(state: KnobState): KnobSnapshot {
  const cached = views.get(state);
  if (cached) {
    return cached;
  }
  const value = displayed(state);
  const percent = fractionOf(value, state, state.scale);
  const view: KnobSnapshot = {
    anchor: state.anchor,
    anchorPercent:
      state.anchor === undefined
        ? 0
        : fractionOf(state.anchor, state, state.scale),
    angle: START_ANGLE + percent * SWEEP_ANGLE,
    disabled: state.disabled,
    dragMode: state.dragMode,
    dragging: state.dragging,
    formatted: numberFormatter(
      state.locale as string | undefined,
      state.format
    ).format(value),
    largeStep: state.largeStep,
    max: state.max,
    min: state.min,
    percent,
    scale: state.scale,
    step: state.step,
    value,
  };
  views.set(state, view);
  return view;
}

/**
 * The value one notch from `current`: a step on a linear scale, a share of
 * the travel on any other, and always at least one step.
 */
function notch(
  state: KnobState,
  current: number,
  direction: -1 | 1,
  large: boolean
) {
  if (state.scale === "linear") {
    return stepBy(
      current,
      { direction, size: large ? "large" : "step" },
      range(state)
    );
  }
  const position =
    fractionOf(current, state, state.scale) +
    direction * (large ? LARGE_POSITION_STEP : POSITION_STEP);
  const next = valueAt(clamp(position, 0, 1), state, state.scale);
  return Math.abs(next - current) < state.step
    ? current + direction * state.step
    : next;
}

/** The `d` of an arc along the dial between two positions, 0 to 1. */
function arcPath(radius: number, from: number, to: number) {
  const point = (t: number) => {
    const angle = ((START_ANGLE + t * SWEEP_ANGLE - 90) * Math.PI) / 180;
    return {
      x: VIEWBOX_CENTER + radius * Math.cos(angle),
      y: VIEWBOX_CENTER + radius * Math.sin(angle),
    };
  };
  const start = point(from);
  const end = point(to);
  const largeArc = (to - from) * SWEEP_ANGLE > 180 ? 1 : 0;
  return `M ${start.x} ${start.y} A ${radius} ${radius} 0 ${largeArc} 1 ${end.x} ${end.y}`;
}

/** The `d` of an arc from `from` to `to` along the sweep, or null when there is none to draw. */
export function arcOf(strokeWidth: number, from: number, to: number) {
  return Math.abs(to - from) > 0.001
    ? arcPath(ARC_OUTER_RADIUS - strokeWidth / 2, from, to)
    : null;
}

/** Where the indicator's arc runs: from the anchor to the value, either way. */
export const indicatorSpan = (view: KnobSnapshot) =>
  [
    Math.min(view.anchorPercent, view.percent),
    Math.max(view.anchorPercent, view.percent),
  ] as const;

/** The angle of a pointer around the centre of `rect`, in radians, 0 pointing right. */
const pointerAngle = (x: number, y: number, rect: DOMRect) =>
  Math.atan2(
    y - (rect.top + rect.height / 2),
    x - (rect.left + rect.width / 2)
  );

/** One pointer drag, from press to release. */
interface Gesture {
  /** Whether the gesture changed the value at least once; if so its end commits, even back on the start value. */
  changed: boolean;
  lastAngle: number;
  lastY: number;
  /** Farthest distance from the press point, in px. */
  maxDistance: number;
  /** How far the drag has taken the dial, 0 to 1 and beyond, accumulated so Shift can make any stretch finer. */
  position: number;
  rect: DOMRect;
  startX: number;
  startY: number;
}

/** The value a gesture has turned the knob to, after one pointer move. */
function turn(state: KnobState, gesture: Gesture, event: PointerEvent) {
  const speed = event.shiftKey ? FINE_DRAG : 1;
  if (state.dragMode === "vertical") {
    gesture.position +=
      ((gesture.lastY - event.clientY) / VERTICAL_DRAG_RANGE_PX) * speed;
  } else {
    const { rect } = gesture;
    const angle = pointerAngle(event.clientX, event.clientY, rect);
    const distance = Math.hypot(
      event.clientX - (rect.left + rect.width / 2),
      event.clientY - (rect.top + rect.height / 2)
    );
    const deadZone = Math.max(
      CENTER_DEAD_ZONE_MIN_PX,
      Math.min(rect.width, rect.height) * CENTER_DEAD_ZONE_REL
    );
    if (distance > deadZone) {
      let delta = angle - gesture.lastAngle;
      if (delta > Math.PI) {
        delta -= TAU;
      } else if (delta < -Math.PI) {
        delta += TAU;
      }
      const fullTurn =
        state.dragMode === "revolution" ? TAU : (SWEEP_ANGLE * Math.PI) / 180;
      gesture.position += (delta / fullTurn) * speed;
    }
    gesture.lastAngle = angle;
  }
  gesture.lastY = event.clientY;
  return valueAt(clamp(gesture.position, 0, 1), state, state.scale);
}

/** What the parts of a knob read: its state, drawn. */
export interface KnobPublicState {
  disabled: boolean;
  dragging: boolean;
  dragMode: KnobDragMode;
  formatted: string;
  max: number;
  min: number;
  value: number;
}

/** What the arcs read: the knob's state and the `d` of their path. */
export interface ArcState extends KnobPublicState {
  arc: string | null;
}

const publicState = (state: KnobState): KnobPublicState => {
  const view = viewOf(state);
  return {
    disabled: view.disabled,
    dragging: view.dragging,
    dragMode: view.dragMode,
    formatted: view.formatted,
    max: view.max,
    min: view.min,
    value: view.value,
  };
};

/** The state attributes every part carries. */
const stateAttrs = (state: KnobState) => ({
  "data-disabled": flag(state.disabled),
  "data-drag-mode": state.dragMode,
  "data-dragging": flag(state.dragging),
});

/** What a knob's `api` gives an adapter. */
export interface KnobApi {
  /** Handles a key on the knob's input: arrows, Page Up and Down, Home, End, Delete or Backspace to reset. Returns whether the knob took the key. */
  keyDown: (event: KeyboardEvent) => boolean;
  /** Starts a pointer gesture on `control`: a drag turns the knob, a double tap or an Alt press resets it. */
  press: (event: PointerEvent, control: HTMLElement) => void;
  /** Returns to the default value, reporting a `"reset"` change and commit. */
  reset: (event?: Event) => void;
  /** Moves the knob to `value` from outside, as a property does: no change is reported. */
  set: (value: number) => void;
  /** Sets the value as typed: on the grid, reported and committed. */
  setValue: (value: number, event?: Event) => void;
  /** The value as displayed. */
  value: () => number;
  /** Listens to wheel steps on `element`; returns what removes the listener. */
  wheel: (element: HTMLElement) => () => void;
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The knob's slots, by name, with the props and the public state of each. */
export type KnobSlots = {
  control: SlotDefinition<KnobState, KnobApi, PartProps, KnobPublicState>;
  indicator: SlotDefinition<
    KnobState,
    KnobApi,
    PartProps & { strokeWidth?: number },
    ArcState
  >;
  input: SlotDefinition<
    KnobState,
    KnobApi,
    PartProps & {
      getAriaValueText?: (formatted: string, value: number) => string;
    },
    object
  >;
  label: SlotDefinition<KnobState, KnobApi, PartProps, object>;
  mark: SlotDefinition<
    KnobState,
    KnobApi,
    PartProps & { value: number },
    KnobPublicState
  >;
  root: SlotDefinition<KnobState, KnobApi, PartProps, KnobPublicState>;
  thumb: SlotDefinition<KnobState, KnobApi, PartProps, KnobPublicState>;
  track: SlotDefinition<
    KnobState,
    KnobApi,
    PartProps & { strokeWidth?: number },
    ArcState
  >;
  value: SlotDefinition<KnobState, KnobApi, PartProps, KnobPublicState>;
};

/**
 * The type of `knob`, written out: the kernel's own types its inferred type
 * would name are not exported, so a declaration could not print it.
 */
export interface KnobPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: KnobSlots;
  (
    initialOptions: KnobPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: KnobApi;
    get: () => KnobState;
    types: {
      api: KnobApi;
      options: KnobPrimitiveOptions;
      slots: KnobSlots;
      state: KnobState;
    };
  };
}

/** The state an options object asks for, with the defaults of the knob. */
function stateOf(options: KnobPrimitiveOptions) {
  return {
    anchor: options.anchor,
    defaultValue: options.defaultValue,
    disabled: options.disabled ?? false,
    dragMode: options.dragMode ?? "circular",
    format: options.format,
    largeStep: options.largeStep ?? 10,
    locale: options.locale,
    max: options.max ?? 100,
    min: options.min ?? 0,
    name: options.name,
    scale: options.scale ?? "linear",
    step: options.step ?? 1,
  } satisfies Partial<KnobState>;
}

export const knob: KnobPrimitive = definePrimitive({
  agent: { actions: ["setValue"] },
  api: (context) => {
    const { commit, report, setAtOnce, state } = createReporter(
      context,
      displayed
    );
    const gestures = createGestures<Gesture>(context);
    let lastTapAt = 0;

    /** Ends a gesture: a tap that moved little is a tap, and a second one soon after resets. */
    const finish = (end: PointerEvent, ended: Gesture, allowTap: boolean) => {
      const turned = displayed(state());
      context.store.set({ dragging: false, draft: null } as never);
      if (allowTap && ended.maxDistance <= TAP_MAX_MOVE_PX) {
        const now = performance.now();
        const isDoubleTap = now - lastTapAt <= DOUBLE_TAP_MAX_MS;
        lastTapAt = isDoubleTap ? 0 : now;
        if (isDoubleTap) {
          setAtOnce(resetValue(state()), "reset", end);
        }
        return;
      }
      lastTapAt = 0;
      if (ended.changed) {
        commit(turned, "drag", end);
      }
    };

    return {
      keyDown: (event: KeyboardEvent) => {
        const current = state();
        if (current.disabled) {
          return false;
        }
        if (event.key === "Delete" || event.key === "Backspace") {
          setAtOnce(resetValue(current), "reset", event);
          return true;
        }
        const move = stepFromKey(event);
        if (!move) {
          return false;
        }
        const value = displayed(current);
        let target: number;
        if ("bound" in move && move.bound) {
          target = move.bound === "min" ? current.min : current.max;
        } else if (move.direction) {
          target = notch(current, value, move.direction, move.size === "large");
        } else {
          return false;
        }
        setAtOnce(onGrid(current, target), "keyboard", event);
        return true;
      },
      press: (event: PointerEvent, control: HTMLElement) => {
        if (
          state().disabled ||
          !gestures.accepts(event, (stale) => finish(event, stale, false))
        ) {
          return;
        }
        const current = state();
        // Alt and a press returns to the default, as in a DAW.
        if (event.altKey) {
          setAtOnce(resetValue(current), "reset", event);
          return;
        }
        const rect = control.getBoundingClientRect();
        const started: Gesture = {
          changed: false,
          lastAngle: pointerAngle(event.clientX, event.clientY, rect),
          lastY: event.clientY,
          maxDistance: 0,
          position: fractionOf(displayed(current), current, current.scale),
          rect,
          startX: event.clientX,
          startY: event.clientY,
        };
        context.store.set({ dragging: true } as never);
        gestures.start(control, event, started, {
          onEnd: (end, ended, canceled) => finish(end, ended, !canceled),
          onMove: (move) => {
            started.maxDistance = Math.max(
              started.maxDistance,
              Math.hypot(
                move.clientX - started.startX,
                move.clientY - started.startY
              )
            );
            const now = state();
            const next = onGrid(now, turn(now, started, move));
            if (report(next, "drag", move)) {
              started.changed = true;
              context.store.set({ draft: next } as never);
            }
          },
        });
      },
      reset: (event?: Event) =>
        setAtOnce(
          onGrid(state(), resetValue(state())),
          "reset",
          event ?? new Event("reset")
        ),
      set: (value: number) => context.store.set({ value } as never),
      setValue: (value: number, event?: Event) =>
        setAtOnce(
          onGrid(state(), value),
          "input-change",
          event ?? new Event("change")
        ),
      value: () => displayed(state()),
      wheel: (element: HTMLElement) => {
        const handle = (event: WheelEvent) => {
          const current = state();
          if (current.disabled || event.ctrlKey || event.metaKey) {
            return;
          }
          event.preventDefault();
          if (Math.abs(event.deltaY) < WHEEL_DELTA_EPSILON) {
            return;
          }
          const next = notch(
            current,
            displayed(current),
            event.deltaY < 0 ? 1 : -1,
            false
          );
          setAtOnce(onGrid(current, next), "wheel", event);
        };
        const listening = new AbortController();
        element.addEventListener("wheel", handle, {
          passive: false,
          signal: listening.signal,
        });
        return () => listening.abort();
      },
    };
  },
  controlled: ["value"],
  name: "knob",
  options: {
    anchor: "number",
    defaultValue: "number",
    disabled: "boolean",
    dragMode: "string",
    format: "value",
    largeStep: "number",
    locale: "value",
    max: "number",
    min: "number",
    name: "string",
    onValueChange: "callback",
    onValueCommitted: "callback",
    scale: "value",
    step: "number",
    value: "number",
  },
  slots: (slot) => ({
    control: slot<object, KnobPublicState>({
      attrs: (state: KnobState) => ({
        ...stateAttrs(state),
        style: css({ position: "relative", "touch-action": "none" }),
      }),
      bind: (el, part) => part.api.wheel(el),
      on: {
        pointerdown: (event, { api, el }) => {
          if (el) {
            api.press(event, el);
          }
        },
      },
      state: (state: KnobState) => publicState(state),
    }),
    indicator: slot<{ strokeWidth?: number }, ArcState>({
      attrs: (state: KnobState) => ({
        ...stateAttrs(state),
        "aria-hidden": "true",
        viewBox: "0 0 48 48",
      }),
      props: { strokeWidth: "number" },
      state: (state: KnobState, { props }) => ({
        ...publicState(state),
        arc: arcOf(
          props.strokeWidth ?? DEFAULT_ARC_STROKE_WIDTH,
          ...indicatorSpan(viewOf(state))
        ),
      }),
    }),
    // The native range input: the role, the value and the name live on it.
    input: slot<{
      getAriaValueText?: (formatted: string, value: number) => string;
    }>({
      attrs: (state: KnobState, { id, props }) => {
        const view = viewOf(state);
        return {
          "aria-labelledby": state.labelled ? `${id}-label` : undefined,
          "aria-valuetext": props.getAriaValueText
            ? props.getAriaValueText(view.formatted, view.value)
            : view.formatted,
          disabled: flag(state.disabled),
          max: String(state.max),
          min: String(state.min),
          name: state.name,
          step: String(state.step),
          style: css(VISUALLY_HIDDEN),
          type: "range",
          value: String(view.value),
        };
      },
      on: {
        change: (event, { api, el }) =>
          api.setValue(Number((el as HTMLInputElement).value), event),
        input: (event, { api, el }) =>
          api.setValue(Number((el as HTMLInputElement).value), event),
        keydown: (event, { api }) => {
          if (api.keyDown(event)) {
            event.preventDefault();
          }
        },
      },
      // A formatter, read for its result: "callback" would make it an event in Vue.
      props: { getAriaValueText: "value" },
    }),
    // Names the knob's input, when nothing else does.
    label: slot({
      attrs: (state: KnobState, { id }) => ({
        ...stateAttrs(state),
        id: `${id}-label`,
      }),
      bind: (_el, part) => {
        part.store.set({ labelled: true });
        return () => part.store.set({ labelled: false });
      },
    }),
    mark: slot<{ value: number }, KnobPublicState>({
      attrs: (state: KnobState, { props }) => {
        const view = viewOf(state);
        const position = fractionOf(props.value, state, state.scale);
        const angle = START_ANGLE + position * SWEEP_ANGLE;
        const [lower, upper] = indicatorSpan(view);
        return {
          ...stateAttrs(state),
          "aria-hidden": "true",
          "data-active": flag(
            position >= lower - 1e-9 && position <= upper + 1e-9
          ),
          style: css({
            "--knob-mark-angle": `${angle}deg`,
            inset: "0",
            "pointer-events": "none",
            position: "absolute",
            rotate: `${angle}deg`,
          }),
        };
      },
      props: { value: "number" },
      state: (state: KnobState) => publicState(state),
    }),
    root: slot<object, KnobPublicState>({
      attrs: (state: KnobState) => stateAttrs(state),
      state: (state: KnobState) => publicState(state),
    }),
    thumb: slot<object, KnobPublicState>({
      attrs: (state: KnobState) => ({
        ...stateAttrs(state),
        style: css({ rotate: `${viewOf(state).angle}deg` }),
      }),
      state: (state: KnobState) => publicState(state),
    }),
    track: slot<{ strokeWidth?: number }, ArcState>({
      attrs: (state: KnobState) => ({
        ...stateAttrs(state),
        "aria-hidden": "true",
        viewBox: "0 0 48 48",
      }),
      props: { strokeWidth: "number" },
      state: (state: KnobState, { props }) => ({
        ...publicState(state),
        arc: arcOf(props.strokeWidth ?? DEFAULT_ARC_STROKE_WIDTH, 0, 1),
      }),
    }),
    value: slot<object, KnobPublicState>({
      attrs: (state: KnobState) => ({
        ...stateAttrs(state),
        "aria-live": "off",
      }),
      state: (state: KnobState) => publicState(state),
    }),
  }),
  state: (options: KnobPrimitiveOptions): KnobState => {
    const rest = stateOf(options);
    const base = {
      ...rest,
      draft: null,
      dragging: false,
      labelled: false,
      value: 0,
    } satisfies KnobState;
    return {
      ...base,
      value: options.value ?? options.defaultValue ?? middleOf(base),
    };
  },
  sync: (options: KnobPrimitiveOptions) =>
    options.value === undefined
      ? stateOf(options)
      : { ...stateOf(options), value: options.value },
});

import { createParts, wrappedChild } from "@ui-sdk/web";
import {
  arcOf,
  DEFAULT_ARC_STROKE_WIDTH,
  indicatorSpan,
  type KnobState,
  knob,
  viewOf,
} from "./knob";

/** A thumb's attributes that name its input instead, so they are read once. */
const INPUT_NAMES = ["aria-describedby", "aria-label", "aria-labelledby"];

/**
 * The thumb holds the native range input, which takes focus, the keys, the
 * name and the form value. Its own `input` and `change` events stop at the
 * knob, whose events of those names report the value with a reason.
 */
function renderThumb(thumb: HTMLElement) {
  if (thumb.querySelector("input")) {
    return;
  }
  const part = document.createElement("audio-ui-knob-input");
  const input = document.createElement("input");
  for (const name of INPUT_NAMES) {
    const value = thumb.getAttribute(name);
    if (value !== null) {
      input.setAttribute(name, value);
      thumb.removeAttribute(name);
    }
  }
  for (const type of ["input", "change"]) {
    input.addEventListener(type, (event) => event.stopPropagation());
  }
  part.appendChild(input);
  thumb.appendChild(part);
}

const SVG = "http://www.w3.org/2000/svg";

/** An arc part's `stroke-width` attribute, as the React part's prop. */
const widthOf = (part: Element) =>
  Number(part.getAttribute("stroke-width")) || DEFAULT_ARC_STROKE_WIDTH;

/** Draws an arc in an `<svg>` the part holds, made on first draw, or takes it away. */
function drawArc(part: Element, from: number, to: number) {
  const width = widthOf(part);
  const d = arcOf(width, from, to);
  let svg = part.querySelector("svg");
  if (!svg) {
    svg = document.createElementNS(SVG, "svg");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("style", "display: block; height: 100%; width: 100%");
    svg.setAttribute("viewBox", "0 0 48 48");
    part.appendChild(svg);
  }
  let path = svg.querySelector("path");
  if (!d) {
    path?.remove();
    return;
  }
  if (!path) {
    path = document.createElementNS(SVG, "path");
    path.setAttribute("fill", "none");
    path.setAttribute("stroke", "currentColor");
    path.setAttribute("stroke-linecap", "round");
    svg.appendChild(path);
  }
  path.setAttribute("stroke-width", String(width));
  path.setAttribute("d", d);
}

/** Writes the value's text as one text node's data, so a change restyles nothing else. */
function writeText(part: Element, text: string) {
  const node =
    part.firstChild instanceof Text
      ? part.firstChild
      : part.appendChild(document.createTextNode(""));
  if (node.data !== text) {
    node.data = text;
  }
}

/**
 * What React renders as children, the knob draws here: the arcs and the
 * value's text, from the state the primitive shows, on every change. The
 * knob connects before its parts are parsed, so it draws again once they bind.
 */
function drawParts(
  el: HTMLElement,
  instance: {
    get: () => object;
    subscribe: (listener: () => void) => () => void;
  }
) {
  const draw = () => {
    const view = viewOf(instance.get() as KnobState);
    for (const track of el.querySelectorAll("audio-ui-knob-track")) {
      drawArc(track, 0, 1);
    }
    for (const indicator of el.querySelectorAll("audio-ui-knob-indicator")) {
      drawArc(indicator, ...indicatorSpan(view));
    }
    for (const value of el.querySelectorAll("audio-ui-knob-value")) {
      writeText(value, view.formatted);
    }
  };
  draw();
  queueMicrotask(draw);
  return instance.subscribe(draw);
}

const jsonAttribute = (value: string | null) =>
  value ? JSON.parse(value) : undefined;

/** The whole web adapter of the knob: a tag for each part, and how attributes read. */
export const parts = createParts(knob, {
  control: { display: "block", tag: "audio-ui-knob-control" },
  indicator: { display: "block", tag: "audio-ui-knob-indicator" },
  input: {
    display: "contents",
    tag: "audio-ui-knob-input",
    target: wrappedChild("input"),
  },
  label: { display: "block", tag: "audio-ui-knob-label" },
  mark: "audio-ui-knob-mark",
  root: {
    api: ["setValue"],
    display: "block",
    events: { onValueChange: "input", onValueCommitted: "change" },
    kinds: {
      format: jsonAttribute,
      locale: "string",
      scale: (value) => value ?? undefined,
    },
    render: drawParts,
    state: {
      value: {
        get: (api) => api.value(),
        set: (api, value: number) => api.set(value),
      },
    },
    tag: "audio-ui-knob",
  },
  thumb: { display: "block", render: renderThumb, tag: "audio-ui-knob-thumb" },
  track: { display: "block", tag: "audio-ui-knob-track" },
  value: "audio-ui-knob-value",
});
